<?php

declare(strict_types=1);
namespace App\Service\Quote; use App\Entity\Quote\QuoteRequest; use Psr\Log\LoggerInterface; use Symfony\Bridge\Twig\Mime\TemplatedEmail; use Symfony\Component\Mailer\MailerInterface; use Symfony\Component\Routing\Generator\UrlGeneratorInterface;
final class QuoteRequestMailer { public function __construct(private MailerInterface $mailer,private LoggerInterface $logger,private UrlGeneratorInterface $router,private string $recipient){} public function send(QuoteRequest $quote):void{try{$this->mailer->send((new TemplatedEmail())->from($this->recipient)->to($quote->getEmail())->subject(sprintf('Ihre Angebotsanfrage %s bei Cardnext',$quote->getNumber()))->htmlTemplate('email/quote_customer.html.twig')->context(['quote'=>$quote]));$this->mailer->send((new TemplatedEmail())->from($this->recipient)->to($this->recipient)->subject('Neue Angebotsanfrage '.$quote->getNumber())->htmlTemplate('email/quote_internal.html.twig')->context(['quote'=>$quote,'adminUrl'=>$this->router->generate('cardnext_admin_quote_show',['id'=>$quote->getId()],UrlGeneratorInterface::ABSOLUTE_URL)]));}catch(\Throwable $e){$this->logger->error('Quote request mail failed',['quoteNumber'=>$quote->getNumber(),'exception'=>$e]);}}
}
